max_quarantine_pct = 10

report = [
    ("has_account", "quarantine", 1, 14),
    ("known_currency", "quarantine", 0, 14),
    ("positive_amount", "fail", 0, 14),
    ("within_review_limit", "warn", 1, 14),
]


def decide(action, failed, checked):
    if failed == 0:
        return "pass"
    if action == "warn":
        return "warn"
    if action == "quarantine" and failed * 100 <= max_quarantine_pct * checked:
        return "quarantine"
    return "stop"


for name, action, failed, checked in report:
    print(f"{name}: {failed} of {checked} failed -> {decide(action, failed, checked)}")

print("2 of 20 ->", decide("quarantine", 2, 20))
print("3 of 20 ->", decide("quarantine", 3, 20))
